import{previewFcp}from'./fcp.js';import{groceryFromRecipes}from'./grocery.js';import{searchRecipes}from'./search.js';import{loadCookProgress,loadState,saveCookProgress,saveState}from'./storage.js';
let state=loadState(),preview=null,tab='ingredients';const serving=new Map,checked=new Set,root=document.querySelector('#app'),TIMER_KEY='family-cookbook:timers:v1';if(!root)throw new Error('App root not found.');
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]??c)),uid=p=>`${p}-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,date=n=>n?new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(n):'Never',route=()=>location.hash.replace(/^#\/?/,'').split('/').filter(Boolean),go=p=>location.hash=`#/${p.replace(/^\//,'')}`,find=id=>state.recipes.find(r=>r.id===id),steps=r=>r.directionSections.flatMap(s=>s.steps.map(step=>({section:s.title,step}))),persist=()=>saveState(state),timers=()=>{try{return JSON.parse(localStorage.getItem(TIMER_KEY)??'{}')}catch{return{}}},saveTimers=t=>localStorage.setItem(TIMER_KEY,JSON.stringify(t));
const header=()=>`<header class="site-header"><a class="brand" href="#/"><b>FC</b><span><strong>Family Cookbook</strong><small>Recipes worth keeping</small></span></a><nav><a href="#/">⌂ <span>Home</span></a><a href="#/collections">▦ <span>Collections</span></a><a href="#/grocery">✓ <span>Grocery</span></a></nav><div class="header-actions"><a class="button ghost" href="#/import">⇩ Import</a><a class="button primary" href="#/new">+ Add recipe</a></div></header>`,page=(html,cls='')=>`${header()}<main class="page ${cls}">${html}</main><div id="toast" class="toast" role="status" aria-live="polite"></div>`,toast=m=>{const n=document.querySelector('#toast');if(!n)return;n.textContent=m;n.classList.add('show');setTimeout(()=>n.classList.remove('show'),2300)};
const card=r=>`<article class="recipe-card"><a class="card-image" href="#/recipe/${esc(r.id)}">${r.image?`<img src="${esc(r.image)}" alt="" loading="lazy">`:'<div class="placeholder">Family recipe</div>'}${r.favorite?'<span class="favorite-badge">♥</span>':''}</a><div class="card-body"><span class="eyebrow">${esc(r.category)}</span><h3><a href="#/recipe/${esc(r.id)}">${esc(r.title)}</a></h3><p>${esc(r.description??r.story??r.note??'')}</p><div class="meta">${r.prepMinutes?`<span>◷ ${r.prepMinutes} min prep</span>`:''}${r.smoker?`<span>♨ ${esc(r.smoker.pitTemperatureF??'')}°F</span>`:''}${r.author?`<span>From ${esc(r.author)}</span>`:''}</div></div></article>`;
const searchBox=(q='')=>`<form id="search-form" class="search"><span>⌕</span><input name="q" value="${esc(q)}" placeholder="Search recipes, ingredients, people, or ‘smoker under 60 min’…"><button class="button primary">Search</button></form>`;
