const home=()=>{const q=new URLSearchParams(location.hash.split('?')[1]??'').get('q')??'',results=searchRecipes(state.recipes,q),recent=[...state.recipes].sort((a,b)=>b.createdAt-a.createdAt).slice(0,6),favorites=state.recipes.filter(r=>r.favorite).slice(0,6),again=[...state.recipes].filter(r=>r.lastCookedAt).sort((a,b)=>(b.lastCookedAt??0)-(a.lastCookedAt??0)).slice(0,4),cols=new Map;state.recipes.forEach(r=>r.collections.forEach(n=>cols.set(n,[...(cols.get(n)??[]),r])));const progress=loadCookProgress(),current=progress?find(progress.recipeId):null;if(q)return page(`<a class="text-link" href="#/">← Home</a><h1>Search the cookbook</h1>${searchBox(q)}<div class="section-heading"><h2>${results.length} match${results.length===1?'':'es'}</h2></div>${results.length?`<div class="recipe-grid">${results.map(card).join('')}</div>`:`<div class="empty"><h2>No recipes matched “${esc(q)}”</h2><p>Try an ingredient, family member, cooking method, or collection.</p></div>`}`);return page(`${current?`<div class="resume"><div><span class="eyebrow">Still cooking?</span><strong>${esc(current.title)}</strong><small>Step ${progress.stepIndex+1} of ${steps(current).length}</small></div><a class="button primary" href="#/cook/${esc(current.id)}">Resume cooking</a></div>`:''}<section class="hero"><div><span class="eyebrow">Our family · our food · our stories</span><h1>The recipes we’ll want <em>thirty years from now.</em></h1><p>Find what we love, remember who it came from, and cook it without fighting the screen.</p>${searchBox()}</div><aside>${(favorites[0]??state.recipes[0])?`<a href="#/recipe/${esc((favorites[0]??state.recipes[0]).id)}">${(favorites[0]??state.recipes[0]).image?`<img src="${esc((favorites[0]??state.recipes[0]).image)}" alt="">`:''}<span>Tonight’s idea</span><strong>${esc((favorites[0]??state.recipes[0]).title)}</strong></a>`:''}</aside></section>${again.length?`<section><div class="section-heading"><div><span class="eyebrow">Back by request</span><h2>Cook again</h2></div></div><div class="recipe-grid four">${again.map(card).join('')}</div></section>`:''}<section><div class="section-heading"><div><span class="eyebrow">The ones we keep reaching for</span><h2>Family favorites</h2></div></div>${favorites.length?`<div class="recipe-grid">${favorites.map(card).join('')}</div>`:'<div class="empty">Tap the heart on a recipe to build this shelf.</div>'}</section><section><div class="section-heading"><div><span class="eyebrow">Browse by mood, memory, or method</span><h2>Our collections</h2></div><a href="#/collections">All collections →</a></div><div class="collection-grid">${[...cols.entries()].slice(0,6).map(([n,rs])=>collectionCard(n,rs)).join('')}</div></section><section><div class="section-heading"><div><span class="eyebrow">Fresh in the book</span><h2>Recently added</h2></div></div><div class="recipe-grid four">${recent.map(card).join('')}</div></section><section class="legacy"><div><span class="eyebrow">Nothing gets lost</span><h2>The original cookbook is preserved.</h2><p>Existing browser-imported recipes migrate automatically, and the previous version stays available during the transition.</p></div><a class="button ghost" href="/legacy/index.html" target="_blank" rel="noopener">↗ Open legacy cookbook</a></section>`,'home-page')};
const smoke=r=>r.smoker?`<aside class="smoke"><span class="eyebrow">Fire plan</span><h2>Smoke profile</h2><dl>${r.smoker.pitTemperatureF?`<div><dt>Pit</dt><dd>${r.smoker.pitTemperatureF}°F</dd></div>`:''}${r.smoker.wood?`<div><dt>Wood</dt><dd>${esc(r.smoker.wood)}</dd></div>`:''}${r.smoker.smoke?`<div><dt>Smoke</dt><dd>${esc(r.smoker.smoke)}</dd></div>`:''}${r.smoker.targetInternalF?`<div><dt>Pull</dt><dd>${esc(r.smoker.targetInternalF)}</dd></div>`:''}${r.smoker.time?`<div><dt>Time</dt><dd>${esc(r.smoker.time)}</dd></div>`:''}${r.smoker.restMinutes?`<div><dt>Rest</dt><dd>${r.smoker.restMinutes} min</dd></div>`:''}</dl>${r.smoker.finish?`<p><b>Finish</b><br>${esc(r.smoker.finish)}</p>`:''}</aside>`:'';
const scaled=(raw,cur,base)=>{if(cur===base||!base)return raw;const m=raw.match(/^([0-9]+(?:\.[0-9]+)?)\s+(.*)$/);return m?`${Number((Number(m[1])*cur/base).toFixed(2))} ${m[2]}`:raw};
const detail=r=>{const serves=serving.get(r.id)??r.servings;return page(`<div class="detail-top"><a href="#/">← Cookbook</a><div><button class="round" data-action="favorite" data-id="${esc(r.id)}">${r.favorite?'♥':'♡'}</button><a class="button ghost" href="#/edit/${esc(r.id)}">✎ Edit</a><a class="button primary" href="#/cook/${esc(r.id)}">Start cooking</a></div></div><section class="recipe-hero"><div>${r.image?`<img src="${esc(r.image)}" alt="${esc(r.title)}">`:'<div class="placeholder">Family recipe</div>'}</div><article><span class="eyebrow">${esc(r.category)}</span><h1>${esc(r.title)}</h1>${r.author?`<p>From <strong>${esc(r.author)}</strong>${r.addedBy&&r.addedBy!==r.author?` · added by ${esc(r.addedBy)}`:''}</p>`:''}<p class="lede">${esc(r.description??r.note??'')}</p><div class="stats"><span><b>${serves}</b><small>servings</small></span>${r.prepMinutes?`<span><b>${r.prepMinutes}m</b><small>prep</small></span>`:''}${r.cookMinutes||r.cookLabel?`<span><b>${esc(r.cookMinutes?`${r.cookMinutes}m`:r.cookLabel)}</b><small>cook</small></span>`:''}${r.lastCookedAt?`<span><b>${date(r.lastCookedAt)}</b><small>last cooked</small></span>`:''}</div></article></section>${r.story?`<section class="story"><span class="eyebrow">The story</span><blockquote>${esc(r.story)}</blockquote></section>`:''}<div class="recipe-layout"><div><div class="tabs"><button data-action="tab" data-tab="ingredients" aria-selected="${tab==='ingredients'}">Ingredients</button><button data-action="tab" data-tab="directions" aria-selected="${tab==='directions'}">Directions</button><a href="#/cook/${esc(r.id)}">Cook mode →</a></div>${tab==='ingredients'?`<div class="servings"><span><small>Scale recipe</small><strong>Servings</strong></span><span><button data-action="servings" data-id="${esc(r.id)}" data-delta="-1">−</button><output>${serves}</output><button data-action="servings" data-id="${esc(r.id)}" data-delta="1">+</button></span></div>${r.ingredientSections.map(s=>`<section class="ingredients"><h2>${esc(s.title)}</h2>${s.ingredients.map(i=>`<label class="ingredient ${checked.has(i.id)?'checked':''}"><input type="checkbox" data-action="ingredient" data-id="${esc(i.id)}" ${checked.has(i.id)?'checked':''}><span>${esc(scaled(i.raw,serves,r.servings))}</span></label>`).join('')}</section>`).join('')}`:`${r.directionSections.map(s=>`<section class="directions"><h2>${esc(s.title)}</h2>${s.steps.map((st,i)=>`<div><b>${i+1}</b><p>${esc(st.text)}</p></div>`).join('')}</section>`).join('')}`}<div class="recipe-tools"><button class="button ghost" data-action="add-grocery" data-id="${esc(r.id)}">Add ingredients to grocery list</button><a class="button primary" href="#/cook/${esc(r.id)}">Start cooking</a></div><section class="notes"><div><span class="eyebrow">Family notes</span><h2>What we learned</h2>${r.notes.length?`<ul>${r.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:'<p>No notes yet. Save the tiny changes that make this recipe yours.</p>'}<form data-note="${esc(r.id)}"><input name="note" required placeholder="Kids liked ½ tsp cayenne better"><button class="button ghost">Add note</button></form></div><div><span class="eyebrow">Recipe history</span><h2>Changes over time</h2><ol>${[...r.history].reverse().slice(0,8).map(h=>`<li><strong>${esc(h.summary)}</strong><small>${date(h.at)}${h.by?` · ${esc(h.by)}`:''}</small></li>`).join('')}</ol></div></section></div><aside>${smoke(r)}${r.pitNotes?`<div class="pit"><span class="eyebrow">Pit notes</span><p>${esc(r.pitNotes)}</p></div>`:''}<div class="filed"><span class="eyebrow">Filed under</span>${r.collections.map(c=>`<a href="#/collections/${encodeURIComponent(c)}">${esc(c)}</a>`).join('')}</div></aside></div>`,'detail-page')};
const collections=id=>{if(id){const n=decodeURIComponent(id),rs=state.recipes.filter(r=>r.collections.includes(n));return page(`<a href="#/collections">← Collections</a><span class="eyebrow">Collection</span><h1>${esc(n)}</h1><p>${rs.length} recipe${rs.length===1?'':'s'} in this shelf.</p><div class="recipe-grid">${rs.map(card).join('')}</div>`)}const m=new Map;state.recipes.forEach(r=>r.collections.forEach(n=>m.set(n,[...(m.get(n)??[]),r])));return page(`<span class="eyebrow">Every shelf</span><h1>Collections</h1><p class="intro">A recipe can belong everywhere it makes sense.</p><div class="collection-grid large">${[...m.entries()].sort(([a],[b])=>a.localeCompare(b)).map(([n,rs])=>collectionCard(n,rs)).join('')}</div>`)};
const parse=(value,kind)=>{const groups=[];let cur={title:kind==='ingredients'?'Ingredients':'Directions',lines:[]};value.split('\n').map(x=>x.trim()).forEach(line=>{if(!line)return;const h=line.match(/^\[(.+)]$/);if(h){if(cur.lines.length)groups.push(cur);cur={title:h[1]||'Section',lines:[]}}else cur.lines.push(line.replace(/^\d+[.)]\s*/,'').replace(/^[-•]\s*/,''))});if(cur.lines.length)groups.push(cur);return kind==='ingredients'?groups.map((g,s)=>({id:uid(`is-${s}`),title:g.title,ingredients:g.lines.map((raw,i)=>({id:uid(`i-${i}`),raw,name:raw.replace(/^[\d¼½¾⅓⅔⅛⅜⅝⅞\s/.-]+/,'').replace(/,.*$/,'').trim()||raw}))})):groups.map((g,s)=>({id:uid(`ds-${s}`),title:g.title,steps:g.lines.map((text,i)=>({id:uid(`d-${i}`),text}))}))};
const asText=(r,kind)=>(kind==='ingredients'?r.ingredientSections:r.directionSections).map(s=>`[${s.title}]\n${kind==='ingredients'?s.ingredients.map(i=>i.raw).join('\n'):s.steps.map((st,i)=>`${i+1}. ${st.text}`).join('\n')}`).join('\n\n');
const editor=r=>page(`<section class="editor"><a href="${r?`#/recipe/${esc(r.id)}`:'#/'}">← Cancel</a><span class="eyebrow">${r?'Make it better':'Save something worth keeping'}</span><h1>${r?`Edit ${esc(r.title)}`:'Add a family recipe'}</h1><p class="intro">Start with the food. The extra details can stay out of the way.</p><form id="recipe-form" data-id="${esc(r?.id??'')}"><label class="full">Recipe name<input name="title" required value="${esc(r?.title??'')}"></label><label>Category<input name="category" value="${esc(r?.category??'Family recipes')}"></label><label>From<input name="author" value="${esc(r?.author??'')}" placeholder="Grandma Jean"></label><label class="full">The story<textarea name="story" rows="4">${esc(r?.story??'')}</textarea></label><label>Servings<input name="servings" type="number" min="1" value="${r?.servings??4}"></label><label>Prep minutes<input name="prep" type="number" min="0" value="${r?.prepMinutes??''}"></label><label class="full">Image path<input name="image" value="${esc(r?.image??'')}" placeholder="/recipe-images/my-recipe.webp"></label><label class="full">Ingredients <small>One per line. Use [Section name] for groups.</small><textarea name="ingredients" rows="13" required>${esc(r?asText(r,'ingredients'):'')}</textarea></label><label class="full">Directions <small>One per line. Use [Section name] for stages.</small><textarea name="directions" rows="13" required>${esc(r?asText(r,'directions'):'')}</textarea></label><details class="full"><summary>Cooking details & smoker profile</summary><div class="advanced"><label>Pit temperature °F<input name="pit" type="number" value="${r?.smoker?.pitTemperatureF??''}"></label><label>Target internal<input name="target" value="${esc(r?.smoker?.targetInternalF??'')}"></label><label>Wood<input name="wood" value="${esc(r?.smoker?.wood??'')}"></label><label>Smoke<input name="smoke" value="${esc(r?.smoker?.smoke??'')}"></label><label class="full">Collections<input name="collections" value="${esc(r?.collections.join(', ')??'')}"></label><label class="full">Tags<input name="tags" value="${esc(r?.tags.join(', ')??'')}"></label><label class="full">Pit / cooking notes<textarea name="pitNotes">${esc(r?.pitNotes??'')}</textarea></label></div></details><div class="full actions"><button class="button primary">${r?'Save changes':'Add to cookbook'}</button>${r?`<button type="button" class="button danger" data-action="delete" data-id="${esc(r.id)}">Delete recipe</button>`:''}</div></form></section>`,'editor-shell');
const importPage=()=>page(`<section class="import"><a href="#/">← Home</a><span class="eyebrow">Bring recipes home</span><h1>Import a Family Cookbook Package</h1><p class="intro">Preview everything first. Nothing is written until you approve it.</p><div class="drop" id="drop-zone"><b>⇩</b><h2>Drop a .fcp file here</h2><p>or choose one from Files</p><label class="button primary" for="fcp-file">Choose .fcp file</label><input id="fcp-file" type="file" hidden></div>${preview?`<section class="preview"><div class="section-heading"><div><span class="eyebrow">Ready to review</span><h2>${esc(preview.packageName||'Cookbook package')}</h2></div><span>${preview.recipes.length} recipe${preview.recipes.length===1?'':'s'}</span></div>${preview.duplicateIds.length?`<div class="warning"><b>${preview.duplicateIds.length} possible duplicate${preview.duplicateIds.length===1?'':'s'}</b><p>Matching titles will be updated rather than duplicated.</p></div>`:''}${preview.warnings.length?`<div class="warning subtle"><b>Review these details</b><ul>${preview.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>`:''}<div class="preview-list">${preview.recipes.map(r=>`<article>${r.image?`<img src="${esc(r.image)}" alt="">`:''}<div><span class="eyebrow">${esc(r.category)}</span><h3>${esc(r.title)}</h3><p>${r.ingredientSections.flatMap(s=>s.ingredients).length} ingredients · ${steps(r).length} steps${r.smoker?' · smoker profile':''}</p></div></article>`).join('')}</div><div class="actions"><button class="button primary" data-action="commit-import">Add to cookbook</button><button class="button ghost" data-action="clear-import">Choose another file</button></div></section>`:''}</section>`);
const grocery=()=>page(`<span class="eyebrow">One trip, less chaos</span><h1>Grocery list</h1><p class="intro">Add ingredients from any recipe. Everything stays in one list.</p>${state.grocery.length?`<div class="grocery">${state.grocery.map(i=>`<label class="${i.checked?'checked':''}"><input type="checkbox" data-action="grocery-check" data-id="${esc(i.id)}" ${i.checked?'checked':''}><span>${esc(i.name)}</span><small>${i.recipeIds.length} recipe${i.recipeIds.length===1?'':'s'}</small></label>`).join('')}</div><div class="actions"><button class="button ghost" data-action="clear-checked">Clear checked</button><button class="button danger" data-action="clear-grocery">Clear list</button></div>`:'<div class="empty"><h2>Your list is empty.</h2><p>Open a recipe and add its ingredients.</p><a class="button primary" href="#/">Browse recipes</a></div>'}`);
const relevant=(r,text)=>{const low=text.toLowerCase();return r.ingredientSections.flatMap(s=>s.ingredients).filter(i=>i.name.toLowerCase().split(/\s+/).filter(w=>w.length>=4).some(w=>low.includes(w))).slice(0,8)},mins=text=>[...text.matchAll(/(\d+)\s*(?:–|-|to)?\s*(\d+)?\s*minutes?/gi)].map(m=>Number(m[2]??m[1])).filter(n=>n>0&&n<=240);
const cook=r=>{const all=steps(r),saved=loadCookProgress(),index=saved?.recipeId===r.id?Math.min(saved.stepIndex,all.length-1):0,current=all[index];if(!current)return page('<div class="empty"><h1>No directions yet.</h1></div>');if(!saved||saved.recipeId!==r.id)saveCookProgress({recipeId:r.id,stepIndex:index,startedAt:Date.now(),updatedAt:Date.now()});const ing=relevant(r,current.step.text),times=mins(current.step.text);return`<main class="cook"><header><a href="#/recipe/${esc(r.id)}">×</a><div><span>${esc(r.title)}</span><strong>Step ${index+1} of ${all.length}</strong></div><button data-action="finish" data-id="${esc(r.id)}">Finish</button></header><div class="progress"><span style="width:${(index+1)/all.length*100}%"></span></div><section><span class="eyebrow">${esc(current.section)}</span><small>${String(index+1).padStart(2,'0')}</small><p>${esc(current.step.text)}</p>${times.length?`<div class="timer-actions">${times.map(n=>`<button data-action="timer" data-minutes="${n}" data-label="${esc(`${r.title} · step ${index+1}`)}">◷ Start ${n} min timer</button>`).join('')}</div>`:''}${ing.length?`<aside class="step-ing"><b>Ingredients in this step</b>${ing.map(i=>`<span>${esc(i.raw)}</span>`).join('')}</aside>`:''}${r.smoker&&(index===0||/smok|temperature|internal|pit/i.test(current.step.text))?`<aside class="cook-smoke"><b>♨ Pit check</b><span>${r.smoker.pitTemperatureF?`${r.smoker.pitTemperatureF}°F`:''}${r.smoker.targetInternalF?` · pull at ${esc(r.smoker.targetInternalF)}`:''}</span><small>${esc(r.smoker.smoke??'')}</small></aside>`:''}</section><footer><button class="button ghost" data-action="cook-step" data-id="${esc(r.id)}" data-delta="-1" ${index===0?'disabled':''}>← Previous</button><button class="button primary" data-action="cook-step" data-id="${esc(r.id)}" data-delta="1">${index===all.length-1?'Finish cooking':'Next step →'}</button></footer></main>`};
const render=()=>{const[s,id]=route();if(s==='recipe'){const r=find(id);root.innerHTML=r?detail(r):page('<div class="empty">Recipe not found.</div>')}else if(s==='edit'){const r=find(id);root.innerHTML=r?editor(r):page('<div class="empty">Recipe not found.</div>')}else if(s==='new')root.innerHTML=editor();else if(s==='collections')root.innerHTML=collections(id);else if(s==='import')root.innerHTML=importPage();else if(s==='grocery')root.innerHTML=grocery();else if(s==='cook'){const r=find(id);root.innerHTML=r?cook(r):page('<div class="empty">Recipe not found.</div>')}else root.innerHTML=home()};
const saveForm=form=>{const d=new FormData(form),title=String(d.get('title')??'').trim(),ingredientSections=parse(String(d.get('ingredients')??''),'ingredients'),directionSections=parse(String(d.get('directions')??''),'directions');if(!title||!ingredientSections.length||!directionSections.length)return toast('Recipe name, ingredients, and directions are required.');const old=find(form.dataset.id),now=Date.now(),collections=String(d.get('collections')??'').split(',').map(x=>x.trim()).filter(Boolean),tags=String(d.get('tags')??'').split(',').map(x=>x.trim()).filter(Boolean),pit=Number(d.get('pit'))||undefined,target=String(d.get('target')??'').trim(),wood=String(d.get('wood')??'').trim(),smokeText=String(d.get('smoke')??'').trim(),smoker=pit||target||wood||smokeText?{pitTemperatureF:pit,targetInternalF:target||undefined,wood:wood||undefined,smoke:smokeText||undefined}:undefined,r={id:old?.id??uid('recipe'),title,category:String(d.get('category')??'').trim()||'Family recipes',author:String(d.get('author')??'').trim()||undefined,addedBy:old?.addedBy??'Family',story:String(d.get('story')??'').trim()||undefined,image:String(d.get('image')??'').trim()||undefined,servings:Math.max(1,Number(d.get('servings'))||4),prepMinutes:Number(d.get('prep'))||undefined,tags,collections:collections.length?collections:[String(d.get('category')??'').trim()||'Family recipes'],ingredientSections,directionSections,smoker,pitNotes:String(d.get('pitNotes')??'').trim()||undefined,notes:old?.notes??[],favorite:old?.favorite??false,createdAt:old?.createdAt??now,updatedAt:now,lastCookedAt:old?.lastCookedAt,history:[...(old?.history??[]),{id:uid('history'),at:now,summary:old?'Recipe edited':'Recipe added to the family cookbook',by:'Family'}]};state.recipes=old?state.recipes.map(x=>x.id===old.id?r:x):[r,...state.recipes];persist();go(`recipe/${r.id}`)};
const handleFile=async file=>{try{preview=await previewFcp(file,state.recipes);render()}catch(err){alert(err instanceof Error?err.message:'Could not read that package.')}};
root.addEventListener('click',ev=>{const t=ev.target.closest('[data-action]');if(!t)return;const a=t.dataset.action,r=find(t.dataset.id);if(a==='favorite'&&r){r.favorite=!r.favorite;persist();render()}if(a==='tab'){tab=t.dataset.tab;render()}if(a==='servings'&&r){serving.set(r.id,Math.max(1,(serving.get(r.id)??r.servings)+Number(t.dataset.delta)));render()}if(a==='ingredient'){t.checked?checked.add(t.dataset.id):checked.delete(t.dataset.id);t.closest('.ingredient')?.classList.toggle('checked',t.checked)}if(a==='add-grocery'&&r){groceryFromRecipes([r]).forEach(x=>{if(!state.grocery.some(i=>i.name.toLowerCase()===x.name.toLowerCase()))state.grocery.push(x)});persist();toast('Ingredients added to grocery list.')}if(a==='grocery-check'){const i=state.grocery.find(x=>x.id===t.dataset.id);if(i){i.checked=t.checked;persist();render()}}if(a==='clear-checked'){state.grocery=state.grocery.filter(i=>!i.checked);persist();render()}if(a==='clear-grocery'&&confirm('Clear the whole grocery list?')){state.grocery=[];persist();render()}if(a==='clear-import'){preview=null;render()}if(a==='commit-import'&&preview){preview.recipes.forEach(n=>{const old=state.recipes.find(x=>x.title.toLowerCase()===n.title.toLowerCase());if(old)state.recipes=state.recipes.map(x=>x.id===old.id?{...n,id:old.id,createdAt:old.createdAt,history:[...old.history,{id:uid('history'),at:Date.now(),summary:'Updated from .fcp package'}]}:x);else state.recipes.unshift(n)});persist();const n=preview.recipes.length;preview=null;go('');setTimeout(()=>toast(`Imported ${n} recipe${n===1?'':'s'}.`),30)}if(a==='delete'&&r&&confirm(`Delete “${r.title}”?`)){state.recipes=state.recipes.filter(x=>x.id!==r.id);persist();go('')}if(a==='cook-step'&&r){const all=steps(r),p=loadCookProgress(),cur=p?.recipeId===r.id?p.stepIndex:0,next=cur+Number(t.dataset.delta);if(next>=all.length){r.lastCookedAt=Date.now();r.history.push({id:uid('history'),at:Date.now(),summary:'Cooked this recipe'});persist();saveCookProgress(null);go(`recipe/${r.id}`)}else{saveCookProgress({recipeId:r.id,stepIndex:Math.max(0,next),startedAt:p?.startedAt??Date.now(),updatedAt:Date.now()});render()}}if(a==='finish'&&r){r.lastCookedAt=Date.now();r.history.push({id:uid('history'),at:Date.now(),summary:'Cooked this recipe'});persist();saveCookProgress(null);go(`recipe/${r.id}`)}if(a==='timer'){const n=Number(t.dataset.minutes),all=timers();all[uid('timer')]={label:t.dataset.label??'Cook timer',endsAt:Date.now()+n*60000};saveTimers(all);toast(`${n} minute timer started.`)}});
root.addEventListener('submit',ev=>{const f=ev.target;if(f.id==='search-form'){ev.preventDefault();const q=String(new FormData(f).get('q')??'').trim();location.hash=q?`#/?q=${encodeURIComponent(q)}`:'#/'}if(f.id==='recipe-form'){ev.preventDefault();saveForm(f)}if(f.dataset.note){ev.preventDefault();const r=find(f.dataset.note),note=String(new FormData(f).get('note')??'').trim();if(r&&note){r.notes.push(note);r.history.push({id:uid('history'),at:Date.now(),summary:'Family note added'});persist();render();toast('Note saved.')}}});
root.addEventListener('change',ev=>{const i=ev.target;if(i.id==='fcp-file'&&i.files?.[0])handleFile(i.files[0])});root.addEventListener('dragover',ev=>{if(ev.target.closest('#drop-zone')){ev.preventDefault();ev.target.closest('#drop-zone').classList.add('dragging')}});root.addEventListener('dragleave',ev=>ev.target.closest('#drop-zone')?.classList.remove('dragging'));root.addEventListener('drop',ev=>{const z=ev.target.closest('#drop-zone');if(!z)return;ev.preventDefault();z.classList.remove('dragging');const f=ev.dataTransfer?.files[0];if(f)handleFile(f)});window.addEventListener('hashchange',()=>{tab='ingredients';render();scrollTo(0,0)});window.addEventListener('keydown',ev=>{if(ev.key==='/'&&!['INPUT','TEXTAREA'].includes(ev.target.tagName)){ev.preventDefault();go('');setTimeout(()=>document.querySelector('#recipe-search')?.focus(),40)}if(route()[0]==='cook'&&(ev.key==='ArrowRight'||ev.key==='ArrowLeft'))document.querySelector(`[data-action="cook-step"][data-delta="${ev.key==='ArrowRight'?'1':'-1'}"]`)?.click()});if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});setInterval(()=>{const now=Date.now(),all=timers();for(const[k,v]of Object.entries(all))if(v.endsAt<=now){delete all[k];saveTimers(all);alert(`Timer finished: ${v.label}`)}},1000);render();
